const nextConfig = {
	webpack: (config, { buildId, dev, isServer, defaultLoaders, nextRuntime, webpack }) => {
		if (config.cache && !dev) {
			config.cache = Object.freeze({
				type: 'memory',
			})
		}
		// Important: return the modified config
		return config
	},
}

export default nextConfig

